function expandYears(y){const p=String(y).split("-");const f=s=>{s=String(s).trim();return s.length===2?("20"+s):s;};return f(p[0])+"-"+f(p[1]||p[0]);}
function parseMotors(str){
  return String(str).split(";").map(s=>s.trim()).filter(Boolean).map(s=>{
    const p=s.split("|");const name=p[0].trim();
    const fuel=FUEL_CODE[(p[1]||"E").trim().toUpperCase()]||"essence";
    let power=(p[2]||"").trim();
    if(!power){const m=name.match(/(\d{2,4})\s*$/);if(m)power=m[1];}
    return {name:name,fuel:fuel,power:power?(String(power).replace(/\s*ch$/i,"")+" ch"):""};
  });
}
const MODELS_ALL = RAW.map(r=>[r[0],r[1],expandYears(r[2]),parseMotors(r[3])]);

